        return ADCS_E_NULL;
    }
    if ((!adcs_is_finite_vec3(vector)) || (!adcs_is_finite_vec3(axis)) ||
        (!isfinite(angle_rad))) {
        *rotated = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }
    {
        adcs_vec3_t u;
        adcs_vec3_t cross_term;
        adcs_vec3_t term_a;
        adcs_vec3_t term_b;
        adcs_vec3_t term_c;
        adcs_vec3_t sum_ab;
        double dot_uv;
        double cos_a;
        double sin_a;
        double one_minus_cos_a;

        if (adcs_vec3_normalize(axis, ADCS_EPS_NORM, &u) != ADCS_OK) {
            *rotated = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }

        dot_uv = adcs_vec3_dot(&u, vector);
        cos_a = cos(angle_rad);
        sin_a = sin(angle_rad);
        one_minus_cos_a = 1.0 - cos_a;

        term_a = adcs_vec3_scale(vector, cos_a);
        cross_term = adcs_vec3_cross(&u, vector);
        term_b = adcs_vec3_scale(&cross_term, sin_a);
        term_c = adcs_vec3_scale(&u, dot_uv * one_minus_cos_a);

        sum_ab = adcs_vec3_add(&term_a, &term_b);
        *rotated = adcs_vec3_add(&sum_ab, &term_c);
    }
    return ADCS_OK;
}

